import { applyEvent } from './apply.js'

// PayRail retries a delivery for up to 24h; keep the dedupe mark a bit longer
// than that so a retry landing right at the edge of the window can't slip through.
const DELIVERY_SEEN_TTL_MS = 25 * 60 * 60 * 1000

// POST /webhooks/payrail. `req` is { headers, body } (header names lowercased, as Node's http gives them);
// returns { status, body }.
export async function handleWebhook(req, { db, verifySignature }) {
  if (!verifySignature(req)) return { status: 401, body: { error: 'bad signature' } }
  const event = req.body

  // Dedupe on X-Delivery-Id (stable across retries), never on event content:
  // PayRail can legitimately send distinct deliveries with identical payloads
  // (e.g. two partial captures of the same amount).
  const deliveryId = req.headers['x-delivery-id']
  const key = `payrail:${deliveryId}`
  if (await db.hasSeen(key)) return { status: 200, body: { ok: true } }

  // Mark seen before applying so a concurrent duplicate on another instance
  // can't slip through during the (potentially multi-second) apply.
  await db.markSeen(key, DELIVERY_SEEN_TTL_MS)
  await applyEvent(event, { db })
  return { status: 200, body: { ok: true } }
}

