test('a retried delivery is acknowledged but not applied twice', async () => {
  const db = createDb()
  const req = {
    headers: { 'x-delivery-id': 'dlv_1' },
    body: { type: 'payment.captured', data: { paymentId: 'p1', amount: 500 } },
  }
  const first = await handleWebhook(req, { db, verifySignature })
  const retry = await handleWebhook(req, { db, verifySignature })
  assert.equal(first.status, 200)
  assert.equal(retry.status, 200)
  assert.equal(db.ledger.length, 1)
})

test('distinct deliveries with identical payloads both apply', async () => {
  const db = createDb()
  const body = { type: 'payment.captured', data: { paymentId: 'p1', amount: 500 } }
  await handleWebhook({ headers: { 'x-delivery-id': 'dlv_1' }, body }, { db, verifySignature })
  await handleWebhook({ headers: { 'x-delivery-id': 'dlv_2' }, body }, { db, verifySignature })
  assert.equal(db.ledger.length, 2)
})
